use super::*;
thread_local!{static RELEASE_EVENT:std::cell::Cell<Option<(*mut u8,usize)>>=const{std::cell::Cell::new(None)};}
struct ObservedGlobalRelease;
impl AllocationRelease for ObservedGlobalRelease{unsafe fn release(pointer:NonNull<u8>,layout:Layout){unsafe{GlobalAllocationRelease::release(pointer,layout)};RELEASE_EVENT.with(|event|event.set(Some((pointer.as_ptr(),layout.size()))));}}
#[test]
fn parent_allocation_return_owns_genuine_layout_until_actual_full_release(){
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📦️return.json")).unwrap();
    let maximum=fixture["maximumAllocationBytes"].as_u64().unwrap()as usize;let total=fixture["maximumTotalBytes"].as_u64().unwrap()as usize;
    let mut parent=ParentAllocationReturn::<2>::try_new(maximum,total).unwrap();let mut text=fixture["text"].as_str().unwrap().to_owned();let text_pointer=text.as_ptr();let text_capacity=text.capacity();assert_eq!(text_capacity,fixture["expectedTextBytes"].as_u64().unwrap()as usize);
    assert!(!parent.return_text(&mut text,0).unwrap());assert_eq!(text.as_ptr(),text_pointer);assert_eq!(text,fixture["text"].as_str().unwrap());assert!(parent.terminal_is_empty());
    assert!(parent.return_text(&mut text,1).unwrap());assert!(text.is_empty());assert_eq!(text.capacity(),0);assert!(!parent.terminal_is_empty());assert_eq!(parent.retained_bytes(),text_capacity);assert_eq!(parent.slots[0].as_ref().unwrap().pointer.as_ptr().cast_const(),text_pointer);
    let mut values=Vec::<u32>::with_capacity(fixture["emptyVectorCapacity"].as_u64().unwrap()as usize);let vector_capacity=values.capacity();assert_eq!(vector_capacity*std::mem::size_of::<u32>(),fixture["expectedVectorBytes"].as_u64().unwrap()as usize);let vector_pointer=values.as_ptr().cast::<u8>();values.push(9);
    assert_eq!(parent.return_empty_vec(&mut values,1).unwrap_err().kind,ValueRefusalKind::InvariantViolated);assert_eq!(values,[9]);assert_eq!(values.as_ptr().cast::<u8>(),vector_pointer);values.clear();assert!(parent.return_empty_vec(&mut values,1).unwrap());assert_eq!(values.capacity(),0);assert_eq!(parent.slots[1].as_ref().unwrap().pointer.as_ptr().cast_const(),vector_pointer);
    let mut occupied="member".to_owned();let occupied_pointer=occupied.as_ptr();assert!(!parent.return_text(&mut occupied,1).unwrap());assert_eq!(occupied.as_ptr(),occupied_pointer);assert_eq!(occupied,"member");
    let owned=parent.retained_bytes();assert_eq!(parent.close_step(0,maximum),AllocationReturnStep::Pending{released_items:0,released_bytes:0});assert_eq!(parent.close_step(1,fixture["childBytes"].as_u64().unwrap()as usize),AllocationReturnStep::Pending{released_items:0,released_bytes:0});assert_eq!(parent.retained_bytes(),owned);assert!(!parent.terminal_is_empty());
    let mut released=0;for _ in 0..3{match parent.close_step(1,maximum){AllocationReturnStep::Complete=>break,AllocationReturnStep::Pending{released_items,released_bytes}=>{assert!(released_items<=1&&released_bytes<=maximum);released+=released_bytes;}}}assert_eq!(released,fixture["expectedTextBytes"].as_u64().unwrap()as usize+fixture["expectedVectorBytes"].as_u64().unwrap()as usize);assert_eq!(parent.retained_bytes(),0);assert!(parent.terminal_is_empty());
    let mut oversized="x".repeat(fixture["refusedPayloadBytes"].as_u64().unwrap()as usize);let pointer=oversized.as_ptr();let capacity=oversized.capacity();assert_eq!(parent.return_text(&mut oversized,1).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(oversized.as_ptr(),pointer);assert_eq!(oversized.capacity(),capacity);assert_eq!(oversized.len(),fixture["refusedPayloadBytes"].as_u64().unwrap()as usize);assert!(parent.terminal_is_empty());
    assert_eq!(serde_json::to_string(&oversized).unwrap(),serde_json::to_string(&"x".repeat(fixture["refusedPayloadBytes"].as_u64().unwrap()as usize)).unwrap());
    assert_eq!(std::mem::size_of::<u32>(),fixture["emptyVectorElementBytes"].as_u64().unwrap()as usize);
    let mut cumulative=ParentAllocationReturn::<2>::try_new(text_capacity,text_capacity).unwrap();let mut first=fixture["text"].as_str().unwrap().to_owned();assert!(cumulative.return_text(&mut first,1).unwrap());let mut second=Vec::<u32>::with_capacity(vector_capacity);let pointer=second.as_ptr();assert_eq!(cumulative.return_empty_vec(&mut second,1).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(second.as_ptr(),pointer);assert_eq!(second.capacity(),vector_capacity);assert_eq!(cumulative.retained_bytes(),text_capacity);assert_eq!(cumulative.close_step(1,text_capacity),AllocationReturnStep::Pending{released_items:1,released_bytes:text_capacity});assert!(cumulative.terminal_is_empty());
    eprintln!("[DEBUG] genuine parent flat-allocation tokens preserve actual source pointers/layouts, zero/full-slot/4byte refusal and terminal=false until physical full-grant deallocation; original8194 exceeds4096 authority unchanged");
}

#[test]
fn parent_allocation_return_calls_the_actual_global_allocator_only_with_full_authority(){
    RELEASE_EVENT.with(|event|event.set(None));let mut text="writer-child".to_owned();let pointer=text.as_mut_ptr();let capacity=text.capacity();let mut parent=ParentAllocationReturn::<1>::try_new(4096,4096).unwrap();assert!(parent.return_text(&mut text,1).unwrap());assert_eq!(parent.close_with::<ObservedGlobalRelease>(1,4),AllocationReturnStep::Pending{released_items:0,released_bytes:0});assert_eq!(RELEASE_EVENT.with(std::cell::Cell::get),None);assert!(!parent.terminal_is_empty());assert_eq!(parent.close_with::<ObservedGlobalRelease>(1,capacity),AllocationReturnStep::Pending{released_items:1,released_bytes:capacity});assert_eq!(RELEASE_EVENT.with(std::cell::Cell::get),Some((pointer,capacity)));assert!(parent.terminal_is_empty());eprintln!("[DEBUG] intercepted genuine production global-allocator deallocation matches original pointer/layout after full grant; no allocator call under4");
}

#[test]
fn parent_return_byte_owner_preserves_exact_rejected_words_and_genuine_accepted_layout(){
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📦️return.json")).unwrap();let words=serde_json::json!([0,255,1,128]);let mut bytes:Vec<u8>=serde_json::from_value(words.clone()).unwrap();let pointer=bytes.as_mut_ptr();let capacity=bytes.capacity();let mut parent=ParentAllocationReturn::<1>::try_new(fixture["maximumAllocationBytes"].as_u64().unwrap()as usize,fixture["maximumTotalBytes"].as_u64().unwrap()as usize).unwrap();assert!(!parent.return_bytes(&mut bytes,0).unwrap());assert_eq!(bytes.as_ptr(),pointer.cast_const());assert_eq!(serde_json::to_value(&bytes).unwrap(),words);assert!(parent.return_bytes(&mut bytes,1).unwrap());assert!(bytes.is_empty());assert_eq!(bytes.capacity(),0);assert_eq!(parent.slots[0].as_ref().unwrap().pointer.as_ptr(),pointer);assert_eq!(parent.retained_bytes(),capacity);assert!(!parent.terminal_is_empty());RELEASE_EVENT.with(|event|event.set(None));assert_eq!(parent.close_with::<ObservedGlobalRelease>(1,capacity-1),AllocationReturnStep::Pending{released_items:0,released_bytes:0});assert_eq!(RELEASE_EVENT.with(std::cell::Cell::get),None);assert_eq!(parent.close_with::<ObservedGlobalRelease>(1,capacity),AllocationReturnStep::Pending{released_items:1,released_bytes:capacity});assert_eq!(RELEASE_EVENT.with(std::cell::Cell::get),Some((pointer,capacity)));assert!(parent.terminal_is_empty());
    let mut large=vec![b'x';fixture["refusedPayloadBytes"].as_u64().unwrap()as usize];let pointer=large.as_ptr();let capacity=large.capacity();assert_eq!(parent.return_bytes(&mut large,1).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);assert_eq!(large.as_ptr(),pointer);assert_eq!(large.capacity(),capacity);assert_eq!(large.len(),fixture["refusedPayloadBytes"].as_u64().unwrap()as usize);assert!(large.iter().all(|byte|*byte==b'x'));assert!(parent.terminal_is_empty());eprintln!("[DEBUG] byte owner exact words and unique layout retained across zero/refused transfer; only actual full-grant allocator release settles parent");
}

